//! Register access for the Renesas RZ/A1L and RZ/A1H, generated by chiptool from `vendor/rza1.svd`
//! and the transforms in `transforms/` (`tools/gen-pac.sh` regenerates `src/chips/`). Enable exactly
//! one chip feature: `rza1l` or `rza1h`.
//!
//! Every peripheral is a `Copy` handle (`CPG`, `SCIF0`, `INTC`, …); its methods return
//! [`common::Reg`] handles whose reads and writes go through [`mmio`], so a host test can drive
//! register sequences and inspect them.
#![cfg_attr(target_os = "none", no_std)]
#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals)]
#![allow(clippy::all)]

#[cfg(all(feature = "rza1l", feature = "rza1h"))]
compile_error!("rza1-pac: enable exactly one chip feature, `rza1l` or `rza1h`, not both");
#[cfg(not(any(feature = "rza1l", feature = "rza1h")))]
compile_error!("rza1-pac: enable a chip feature, `rza1l` or `rza1h`");

pub mod common;
pub mod mmio;

#[cfg(feature = "rza1l")]
include!("chips/rza1l.rs");
#[cfg(feature = "rza1h")]
include!("chips/rza1h.rs");

#[cfg(all(test, not(target_os = "none")))]
mod tests {
    use super::*;

    #[test]
    fn register_accesses_go_through_the_seam_at_their_width() {
        mmio::test::reset();
        GPIO.pmc(6).write_value(0x0005);
        CPG.stbcr12().write_value(cpg::regs::Stbcr12(0xF0));
        INTC.icdiser(1).write_value(1 << 13);
        let log = mmio::test::log();
        let seen: Vec<_> = log.iter().map(|a| (a.addr, a.width)).collect();
        assert_eq!(seen, [(0xFCFE_3418, 2), (0xFCFE_0444, 1), (0xE820_1104, 4)]);
        assert_eq!(
            mmio::test::writes(),
            [(0xFCFE_3418, 0x0005), (0xFCFE_0444, 0xF0), (0xE820_1104, 1 << 13)]
        );
        mmio::test::poke16(0xFCFE_3218, 0x00A0);
        assert_eq!(GPIO.ppr(6).read(), 0x00A0);
    }

    #[test]
    fn a_register_knows_its_address_and_width() {
        assert_eq!((CPG.frqcr().addr(), CPG.frqcr().width()), (0xFCFE_0010, 2));
        assert_eq!((RSPI0.spdr_byte().addr(), RSPI0.spdr_byte().width()), (0xE800_C804, 1));
        assert_eq!((INTC.icdipr(37).addr(), INTC.icdipr(37).width()), (0xE820_1494, 4));
    }

    /// The RZ/A1L has ten ports, the RZ/A1H twelve.
    #[test]
    fn the_chip_feature_picks_the_port_count() {
        let ports = if cfg!(feature = "rza1l") { 10 } else { 12 };
        let _ = GPIO.p(ports - 1);
        assert!(std::panic::catch_unwind(|| GPIO.p(ports)).is_err());
    }

    fn read_only<T: Copy>(_: common::Reg<T, common::R>) {}
    fn write_only<T: Copy>(_: common::Reg<T, common::W>) {}

    /// Registers whose access has a side effect or no meaning in one direction carry that in
    /// their type: a write to a read-only register, or a read (or `modify`) of a write-only one,
    /// doesn't compile. (The SVD declares everything read-write; `transforms/common/access.yaml`
    /// corrects these.)
    #[test]
    fn side_effecting_registers_carry_their_access() {
        read_only(INTC.icdictr());
        read_only(INTC.icdiidr());
        read_only(INTC.icciar());
        read_only(INTC.iccrpr());
        read_only(INTC.icchpir());
        write_only(INTC.icceoir());
        read_only(SCIF0.frdr());
        write_only(SCIF0.ftdr());
        read_only(OSTM0.cnt());
        read_only(OSTM0.te());
        write_only(OSTM0.ts());
        write_only(OSTM0.tt());
    }

    #[test]
    fn dmac_channels_8_to_15_sit_past_the_group_gap() {
        assert_eq!((DMAC.ch(0).n0sa().addr(), DMAC.ch(0).n0sa().width()), (0xE820_0000, 4));
        assert_eq!(DMAC.ch(7).chctrl().addr(), 0xE820_0000 + 7 * 64 + 0x28);
        assert_eq!(DMAC.ch(8).chctrl().addr(), 0xE820_0000 + 8 * 64 + 0x200 + 0x28);
        assert_eq!(DMAC.ch(15).nxla().addr(), 0xE820_0000 + 15 * 64 + 0x200 + 0x38);
        assert_eq!(DMAC.dctrl(0).addr(), 0xE820_0300);
        assert_eq!(DMAC.dctrl(1).addr(), 0xE820_0700);
        assert_eq!(DMAC.dmars(3).addr(), 0xFCFE_100C);
    }

    #[test]
    fn scux_sub_units_are_indexed_by_unit() {
        assert_eq!(SCUX.ipc(2).ipslr().addr(), 0xE820_8000 + 0x200 + 0x04);
        assert_eq!(SCUX.ffd(1).drqsr().addr(), 0xE820_8800 + 0x100 + 0x08);
        assert_eq!(SCUX.ffu(3).urqsr().addr(), 0xE820_8C00 + 0x300 + 0x08);
        // 2SRC converter 2·unit + pair: unit stride 0x100, pair stride 0x34.
        assert_eq!(SCUX.src(0).srcir().addr(), 0xE820_9000);
        assert_eq!(SCUX.src(1).srcir().addr(), 0xE820_9034);
        assert_eq!(SCUX.src(3).ifsvr().addr(), 0xE820_9000 + 0x100 + 0x34 + 0x10);
        assert_eq!(SCUX.dvu(1).volr(7).addr(), 0xE820_9200 + 0x100 + 0x24 + 7 * 4);
        assert_eq!(SCUX.swrsr_cim().addr(), 0xE820_9700);
    }

    #[test]
    fn usb_fifo_ports_have_byte_views_over_their_lanes() {
        assert_eq!((USB200.cfifo().addr(), USB200.cfifo().width()), (0xE801_0014, 4));
        assert_eq!((USB200.cfifo_b(3).addr(), USB200.cfifo_b(3).width()), (0xE801_0017, 1));
        assert_eq!(USB201.d1fifo_b(0).addr(), 0xE820_701C);
        assert_eq!(USB200.pipectr(0).addr(), 0xE801_0070); // PIPE1CTR
        assert_eq!(USB200.pipectr(14).addr(), 0xE801_008C); // PIPEFCTR
        assert_eq!(USB200.devadd(10).addr(), 0xE801_00D0 + 20); // DEVADDA
        assert_eq!(USB200.intsts(1).addr(), 0xE801_0042);
    }

    #[cfg(feature = "rza1l")]
    #[test]
    fn sdhi_comes_from_the_rza1l_manual() {
        assert_eq!((SDHI0.sd_cmd().addr(), SDHI0.sd_cmd().width()), (0xE804_E000, 2));
        assert_eq!((SDHI1.sd_buf0().addr(), SDHI1.sd_buf0().width()), (0xE804_E830, 4));
        assert_eq!(SDHI1.ext_swap().addr(), 0xE804_E8F0);
    }
}
